/* ── PRESETS ─────────────────────────────────────────────── */
export const PRESET_BASICO = TWEAKS.filter(t =>
  ["game-mode", "xbox-bar", "twk-dvr", "hags", "visual-perf",
   "pwr-ultimate", "start-od", "rem-teams-chat", "clean-temp", "clean-dns"].includes(t.id)
);

export const PRESET_OPTIMO = TWEAKS.filter(t =>
  [
    // Básico
    "game-mode", "xbox-bar", "twk-dvr", "twk-fso", "hags", "visual-perf",
    "twk-gpu-priority", "twk-sys-resp", "process-sep",
    // Panel NVIDIA
    "nv-power", "nv-lowlatency", "nv-threaded", "nv-vsync-off", "nv-reflex",
    "nv-max-frames", "nv-physx-cpu",
    // Energía / CPU
    "pwr-ultimate", "cpu-parking", "power-throttling", "boost-mode", "cpu-min-freq",
    "usb-suspend", "pci-link", "twk-irq-priority",
    // Red
    "net-nagle", "net-throttling", "net-ack-freq", "net-qos-sched", "net-ipv4-ttl",
    // Servicios
    "svc-sysmain", "svc-remote-reg",
    // Privacidad
    "priv-telemetry", "priv-ads", "priv-diagdata", "priv-bing-search", "priv-content-delivery",
    // Inicio automático
    "start-od", "start-delay", "start-nvidia-gfe", "start-corsair",
    // Personalización
    "task-widgets", "task-chat-off", "notif-sounds",
    // Dispositivos
    "dev-mouse", "dev-raw-mouse", "dev-hid-power", "dev-gpu-tdr",
    // Eliminación
    "rem-teams-chat", "rem-xbox-overlay", "rem-edge-autostart",
    // Limpieza
    "clean-temp", "clean-shader", "clean-dns", "clean-dx-shader",
    // Almacenamiento
    "twk-ntfs-last",
  ].includes(t.id)
);

export const PRESET_AVANZADO = TWEAKS;

export const getCategoryTweaks = (cat) => TWEAKS.filter(t => t.category === cat);
export const getImpact = (count) =>
  count > 30 ? '+30-40% FPS' : count > 20 ? '+20-30% FPS' : count > 10 ? '+10-20% FPS' : '+5-10% FPS';
